cd /Users/dct/code/EllyaOrg/projects/dalimaray/observatory-wt/current/apps/observatory-app/ui && cat >> style.css <<'EOF'

.chart-block { display: grid; gap: 6px; margin: 8px 0; }
.chart { display: block; max-width: 100%; }
svg.chart text { fill: var(--muted); font-size: 10px; }
.chart-legend { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 11px; }
.swatch { display: inline-block; width: 10px; height: 10px; margin-right: 4px; }
.seg-waiting-on-human, .state-waiting-on-human { fill: var(--w-human); }
.seg-waiting-on-validation, .state-waiting-on-validation { fill: var(--w-valid); }
.seg-rework, .state-rework { fill: var(--w-rework); }
.seg-retry, .state-retry { fill: var(--w-retry); }
.seg-idle, .state-idle { fill: var(--w-idle); }
.state-active { fill: var(--ok); }
span.swatch.seg-waiting-on-human, span.swatch.state-waiting-on-human { background: var(--w-human); }
span.swatch.seg-waiting-on-validation, span.swatch.state-waiting-on-validation { background: var(--w-valid); }
span.swatch.seg-rework, span.swatch.state-rework { background: var(--w-rework); }
span.swatch.seg-retry, span.swatch.state-retry { background: var(--w-retry); }
span.swatch.seg-idle, span.swatch.state-idle { background: var(--w-idle); }
span.swatch.state-active { background: var(--ok); }
.rework-window { fill: none; stroke: var(--bad); stroke-width: 1.5; }
.rework-window.unresolved { stroke-dasharray: 4 2; }
.spark { fill: none; stroke: var(--info); stroke-width: 1.5; }
EOF
cd ../../.. && grep -c throttled apps/observatory-app/ui/src/panel_charts.rs; python3 scripts/check-kit.py 2>&1 | tail -8

